-- Emu's schema as it stood when it moved from SQLite to Postgres (ADR 0006).
--
-- Names that were unique "COLLATE NOCASE" in SQLite are unique on lower(name) here. The names
-- are in the "C" collation, so lower() folds A-Z only and ordering is by code point, exactly as
-- SQLite did, whatever locale the database was created with.
--
-- Ids are "GENERATED BY DEFAULT" so the importer can copy the ids of an existing database; it
-- moves each sequence past the highest id afterwards.

CREATE TABLE settings (
    key   text PRIMARY KEY,
    value text NOT NULL
);

-- Stock -------------------------------------------------------------------------------------

CREATE TABLE ingredients (
    id                integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    name              text COLLATE "C" NOT NULL,
    base_unit         text NOT NULL,
    shelf_life_amount integer,
    shelf_life_unit   text,
    last_quantity     double precision,
    last_unit         text,
    kcal              double precision,
    reviewed          boolean NOT NULL DEFAULT false
);
CREATE UNIQUE INDEX ingredients_name_key ON ingredients (lower(name));

CREATE TABLE ingredient_food_groups (
    ingredient_id integer NOT NULL REFERENCES ingredients (id) ON DELETE CASCADE,
    food_group    text NOT NULL,
    PRIMARY KEY (ingredient_id, food_group)
);

CREATE TABLE ingredient_allergens (
    ingredient_id integer NOT NULL REFERENCES ingredients (id) ON DELETE CASCADE,
    allergen      text NOT NULL,
    PRIMARY KEY (ingredient_id, allergen)
);

CREATE TABLE stock_items (
    id            integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    ingredient_id integer NOT NULL REFERENCES ingredients (id),
    quantity      double precision NOT NULL CHECK (quantity >= 0),
    location      text NOT NULL,
    expires_on    date
);
CREATE INDEX stock_items_ingredient ON stock_items (ingredient_id);

CREATE TABLE product_cache (
    barcode   text PRIMARY KEY,
    name      text,
    quantity  double precision,
    unit      text,
    kcal_100g double precision
);

-- Recipes -----------------------------------------------------------------------------------

CREATE TABLE recipes (
    id         integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    name       text COLLATE "C" NOT NULL,
    servings   integer NOT NULL CHECK (servings >= 1),
    weather    text NOT NULL DEFAULT 'any',
    source_url text
);
CREATE UNIQUE INDEX recipes_name_key ON recipes (lower(name));

CREATE TABLE recipe_meal_types (
    recipe_id integer NOT NULL REFERENCES recipes (id) ON DELETE CASCADE,
    meal_type text NOT NULL,
    PRIMARY KEY (recipe_id, meal_type)
);

CREATE TABLE recipe_tags (
    recipe_id integer NOT NULL REFERENCES recipes (id) ON DELETE CASCADE,
    tag       text NOT NULL,
    position  integer NOT NULL,
    PRIMARY KEY (recipe_id, tag)
);

CREATE TABLE recipe_lines (
    recipe_id     integer NOT NULL REFERENCES recipes (id) ON DELETE CASCADE,
    ingredient_id integer NOT NULL REFERENCES ingredients (id),
    quantity      double precision NOT NULL CHECK (quantity > 0),
    position      integer NOT NULL,
    alt_group     integer,
    PRIMARY KEY (recipe_id, ingredient_id)
);
CREATE INDEX recipe_lines_ingredient ON recipe_lines (ingredient_id);

-- Eaters ------------------------------------------------------------------------------------

CREATE TABLE eaters (
    id                 integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    name               text COLLATE "C" NOT NULL,
    category           text NOT NULL,
    calorie_adjustment integer NOT NULL DEFAULT 0,
    diet               text NOT NULL DEFAULT 'omnivore'
);
CREATE UNIQUE INDEX eaters_name_key ON eaters (lower(name));

CREATE TABLE eater_terms (
    eater_id integer NOT NULL REFERENCES eaters (id) ON DELETE CASCADE,
    kind     text NOT NULL CHECK (kind IN ('allergy', 'dislike')),
    term     text NOT NULL,
    position integer NOT NULL,
    PRIMARY KEY (eater_id, kind, term)
);

CREATE TABLE eater_allergens (
    eater_id integer NOT NULL REFERENCES eaters (id) ON DELETE CASCADE,
    allergen text NOT NULL,
    PRIMARY KEY (eater_id, allergen)
);

CREATE TABLE category_goals (
    category text PRIMARY KEY,
    kcal     integer NOT NULL
);

-- Occasions ---------------------------------------------------------------------------------

CREATE TABLE occasions (
    id            integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    name          text COLLATE "C" NOT NULL,
    day           date NOT NULL,
    headcount     integer,
    extra_percent integer NOT NULL DEFAULT 0,
    source        text NOT NULL DEFAULT 'manual' CHECK (source IN ('manual', 'holiday'))
);
CREATE INDEX occasions_day ON occasions (day);
CREATE UNIQUE INDEX occasions_holiday ON occasions (day, lower(name)) WHERE source = 'holiday';

CREATE TABLE occasion_tags (
    occasion_id integer NOT NULL REFERENCES occasions (id) ON DELETE CASCADE,
    tag         text NOT NULL,
    position    integer NOT NULL,
    PRIMARY KEY (occasion_id, tag)
);

-- Weather -----------------------------------------------------------------------------------

CREATE TABLE weather_days (
    day  date PRIMARY KEY,
    high double precision NOT NULL,
    low  double precision NOT NULL
);

-- Menus -------------------------------------------------------------------------------------

CREATE TABLE menus (
    id             integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    name           text NOT NULL,
    start_day      date NOT NULL,
    days           integer NOT NULL,
    accepted_on    date,
    accepted_order integer
);

CREATE TABLE menu_meals (
    id             integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    menu_id        integer NOT NULL REFERENCES menus (id) ON DELETE CASCADE,
    day            date NOT NULL,
    slot           text NOT NULL,
    recipe_id      integer REFERENCES recipes (id) ON DELETE SET NULL,
    reason         text NOT NULL DEFAULT '',
    cooked_on      date,
    short          text NOT NULL DEFAULT '',
    guests         integer NOT NULL DEFAULT 0,
    guest_servings double precision NOT NULL DEFAULT 0
);
CREATE INDEX menu_meals_menu ON menu_meals (menu_id);
CREATE INDEX menu_meals_recipe ON menu_meals (recipe_id);

-- What a cooked Meal took from Stock, in the order it was taken (by id).
CREATE TABLE menu_meal_taken (
    id         integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    meal_id    integer NOT NULL REFERENCES menu_meals (id) ON DELETE CASCADE,
    ingredient text NOT NULL,
    quantity   double precision NOT NULL,
    unit       text NOT NULL,
    location   text NOT NULL,
    expires_on date
);
CREATE INDEX menu_meal_taken_meal ON menu_meal_taken (meal_id);

CREATE TABLE menu_portions (
    meal_id  integer NOT NULL REFERENCES menu_meals (id) ON DELETE CASCADE,
    eater_id integer NOT NULL REFERENCES eaters (id) ON DELETE CASCADE,
    servings double precision NOT NULL,
    PRIMARY KEY (meal_id, eater_id)
);
CREATE INDEX menu_portions_eater ON menu_portions (eater_id);
